#[test]
fn the_rootfs_identity_is_deterministic_across_runs_and_archive_order() {
    let first = TempDir::new().expect("cas");
    let second = TempDir::new().expect("cas");
    let a = import_fixture(
        Platform::linux("arm64"),
        SymlinkPolicy::Resolve,
        first.path(),
    );
    let b = import_fixture(
        Platform::linux("arm64"),
        SymlinkPolicy::Resolve,
        second.path(),
    );
    assert_eq!(a.rootfs, b.rootfs);
    assert_eq!(
        manifest_bytes(first.path(), &a.rootfs),
        manifest_bytes(second.path(), &b.rootfs)
    );
    // The identity is the BLAKE3 of the manifest bytes: the existing rootfs
    // domain the resolver verifies, not a new construction.
    assert_eq!(a.rootfs.algorithm, "blake3-256");
    assert_eq!(
        a.rootfs.value,
        blake3::hash(&manifest_bytes(first.path(), &a.rootfs))
            .to_hex()
            .to_string()
    );

    // Importing again into the same CAS reuses the verified entry.
    let again = import_fixture(
        Platform::linux("arm64"),
        SymlinkPolicy::Resolve,
        first.path(),
    );
    assert_eq!(again.rootfs, a.rootfs);
    assert_eq!(cas_entries(first.path()), vec![a.rootfs.value.clone()]);

    // The same content archived in a different order: every blob, and so
    // the index digest, differs; the rootfs identity does not.
    let scratch = TempDir::new().expect("scratch");
    let reordered_layout = scratch.path().join("oci");
    let reordered = build_fixture(&reordered_layout, true);
    assert_ne!(reordered.index.digest, fixture().index.digest);
    let third = TempDir::new().expect("cas");
    let c = import(
        &reordered_layout,
        &reordered.index.digest,
        Platform::linux("arm64"),
        SymlinkPolicy::Resolve,
        third.path(),
    )
    .expect("import reordered layout");
    assert_eq!(c.rootfs, a.rootfs);
    assert_eq!(
        manifest_bytes(third.path(), &c.rootfs),
        manifest_bytes(first.path(), &a.rootfs)
    );
}

/// Every directory under `root`, relative, with its mode.
fn directories(root: &Path) -> Vec<(String, u32)> {
    fn walk(root: &Path, dir: &Path, out: &mut Vec<(String, u32)>) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            let meta = path.symlink_metadata().unwrap();
            if meta.is_dir() {
                out.push((
                    path.strip_prefix(root)
                        .unwrap()
                        .to_string_lossy()
                        .into_owned(),
                    meta.permissions().mode() & 0o7777,
                ));
                walk(root, &path, out);
            }
        }
    }
    let mut out = vec![(
        String::new(),
        fs::metadata(root).unwrap().permissions().mode() & 0o7777,
    )];
    walk(root, root, &mut out);
    out.sort();
    out
}

#[test]
fn one_rootfs_digest_names_one_tree_on_disk() {
    // Rootfs manifest v1 lists files only. Directories that hold no file,
    // and directory modes, are not in it, so the importer must not write
    // them: otherwise two images with one digest differ on disk, and which
    // tree a CAS holds depends on which image arrived first.
    let (with_dirs, a) = import_single(
        vec![
            Layer::plain(vec![
                dir("tmp/", 0o1777),
                dir("proc/", 0o555),
                dir("bin/", 0o700),
                file("bin/x", 0o755, b"x"),
                file("var/cache/old", 0o644, b"old"),
            ]),
            // Emptied by an opaque whiteout: an empty directory again.
            Layer::plain(vec![file("var/cache/.wh..wh..opq", 0o644, b"")]),
        ],
        SymlinkPolicy::Refuse,
    );
    let (without, b) = import_single(
        vec![Layer::plain(vec![file("bin/x", 0o755, b"x")])],
        SymlinkPolicy::Refuse,
    );
    let (a, b) = (a.expect("import with empty dirs"), b.expect("import"));
    assert_eq!(a.rootfs, b.rootfs);
    let tree = |scratch: &TempDir, imported: &ImportedRootfs| {
        directories(&scratch.path().join("cas").join(&imported.rootfs.value))
    };
    assert_eq!(tree(&with_dirs, &a), tree(&without, &b));
    assert_eq!(
        tree(&with_dirs, &a),
        vec![(String::new(), 0o755), ("bin".to_string(), 0o755)]
    );
}

