#[test]
fn a_tampered_cas_entry_is_not_reused() {
    let cas = TempDir::new().expect("cas");
    let imported = import_fixture(Platform::linux("arm64"), SymlinkPolicy::Resolve, cas.path());
    let config = cas.path().join(&imported.rootfs.value).join("etc/config");
    let mut permissions = fs::metadata(&config).unwrap().permissions();
    permissions.set_mode(0o644);
    fs::set_permissions(&config, permissions).unwrap();
    fs::write(&config, b"tampered\n").unwrap();
    match import(
        &checked_in_fixture(),
        &fixture().index.digest,
        Platform::linux("arm64"),
        SymlinkPolicy::Resolve,
        cas.path(),
    ) {
        Err(OciImportError::Cas(detail)) => {
            assert!(detail.contains(&imported.rootfs.value), "{detail}")
        }
        other => panic!("expected a CAS refusal, got {other:?}"),
    }
    assert_eq!(
        fs::read(&config).unwrap(),
        b"tampered\n",
        "an import never overwrites a published entry"
    );
    assert_eq!(cas_entries(cas.path()), vec![imported.rootfs.value.clone()]);
}

#[test]
fn a_cas_entry_with_tampered_directories_is_not_reused() {
    // The manifest does not cover directories. The per-run copy no longer
    // carries them into the guest (it is built from the manifest, bead
    // ley-line-open-38ff59), but the importer still keeps its own entries
    // exact: a reused entry must have exactly the directories the import
    // would write, all 0755.
    type Tamper = (&'static str, fn(&Path));
    let tamper: [Tamper; 3] = [
        ("a widened directory", |root| {
            fs::set_permissions(root.join("etc"), fs::Permissions::from_mode(0o777)).unwrap()
        }),
        ("a planted directory", |root| {
            fs::create_dir(root.join("planted")).unwrap()
        }),
        ("a widened root", |root| {
            fs::set_permissions(root, fs::Permissions::from_mode(0o1777)).unwrap()
        }),
    ];
    for (what, tamper) in tamper {
        let cas = TempDir::new().expect("cas");
        let imported = import_fixture(Platform::linux("arm64"), SymlinkPolicy::Resolve, cas.path());
        tamper(&cas.path().join(&imported.rootfs.value));
        match import(
            &checked_in_fixture(),
            &fixture().index.digest,
            Platform::linux("arm64"),
            SymlinkPolicy::Resolve,
            cas.path(),
        ) {
            Err(OciImportError::Cas(detail)) => {
                assert!(detail.contains("directories"), "{what}: {detail}")
            }
            other => panic!("{what}: expected a CAS refusal, got {other:?}"),
        }
    }
}

