#[test]
fn documents_are_bounded_at_four_mebibytes() {
    // JSON tolerates trailing whitespace: pad an index to exactly the bound
    // (accepted) and one byte past it (refused).
    let scratch = TempDir::new().expect("scratch");
    let layout_dir = scratch.path().join("oci");
    let layout = Layout::create(&layout_dir);
    let image = layout.image(
        "linux",
        "arm64",
        &[Layer::plain(vec![file("a", 0o644, b"a")])],
        None,
    );
    let index = serde_json::to_vec(&serde_json::json!({
        "schemaVersion": 2,
        "mediaType": OCI_INDEX,
        "manifests": [{
            "mediaType": OCI_MANIFEST,
            "digest": image.digest,
            "size": image.size,
            "platform": {"architecture": "arm64", "os": "linux"}
        }]
    }))
    .unwrap();
    let padded = |length: usize| {
        let mut bytes = index.clone();
        bytes.resize(length, b' ');
        layout.blob(OCI_INDEX, &bytes)
    };
    let cas = scratch.path().join("cas");
    fs::create_dir(&cas).unwrap();
    let attempt = |digest: &str| {
        import(
            &layout_dir,
            digest,
            Platform::linux("arm64"),
            SymlinkPolicy::Refuse,
            &cas,
        )
    };
    assert_eq!(
        attempt(&padded(4 << 20).digest)
            .expect("at the bound")
            .files,
        1
    );
    assert!(matches!(
        attempt(&padded((4 << 20) + 1).digest),
        Err(OciImportError::Unsupported(_))
    ));
}

#[test]
fn hostile_paths_are_refused_and_nothing_escapes() {
    let cases: Vec<(Vec<Entry>, &str)> = vec![
        (vec![file("../evil", 0o644, b"x")], "../evil"),
        (vec![file("a/../../evil", 0o644, b"x")], "a/../../evil"),
        (vec![file("/abs/evil", 0o644, b"x")], "/abs/evil"),
        (vec![dir("/", 0o755)], "/"),
        (
            vec![symlink("link", "/etc"), file("link/passwd", 0o644, b"x")],
            "link/passwd",
        ),
        (
            vec![symlink("link", "../.."), file("link/evil", 0o644, b"x")],
            "link/evil",
        ),
        (vec![hardlink("h", "../outside")], "h"),
        (vec![hardlink("h", "missing")], "h"),
        (vec![dir("d/", 0o755), hardlink("h", "d")], "h"),
        (vec![file("../.wh.x", 0o644, b"")], "../.wh.x"),
        (vec![file("x/.wh..wh.plnk", 0o644, b"")], "x/.wh..wh.plnk"),
        (vec![file("x/.wh.", 0o644, b"")], "x/.wh."),
        (
            vec![file("rootfs.manifest.json", 0o644, b"{}")],
            "rootfs.manifest.json",
        ),
        (
            vec![file("f", 0o644, b"f"), file("f/child", 0o644, b"c")],
            "f/child",
        ),
        (vec![file(".", 0o644, b"x")], "."),
    ];
    for (entries, named) in cases {
        let (scratch, result) = import_single(vec![Layer::plain(entries)], SymlinkPolicy::Resolve);
        match result {
            Err(OciImportError::UnsafePath {
                layer,
                path,
                reason,
            }) => {
                assert_eq!(layer, 0);
                assert_eq!(path, named);
                if named == "link/passwd" {
                    assert_eq!(reason, "the path passes through a symbolic link");
                }
            }
            other => panic!("expected UnsafePath for {named}, got {other:?}"),
        }
        assert!(!scratch.path().join("evil").exists());
        assert!(cas_entries(&scratch.path().join("cas")).is_empty());
    }
    // A link whose resolution climbs above the image root is refused, not
    // clamped at `/` the way the guest kernel would.
    for (target, link) in [("../../../../etc/passwd", "esc"), ("/../etc", "esc")] {
        let (_scratch, result) = import_single(
            vec![Layer::plain(vec![
                file("etc/passwd", 0o644, b"root"),
                symlink(link, target),
            ])],
            SymlinkPolicy::Resolve,
        );
        match result {
            Err(OciImportError::SymlinkUnresolvable { path, .. }) => assert_eq!(path, link),
            other => panic!("expected SymlinkUnresolvable for {target}, got {other:?}"),
        }
    }
}

